/*
 * harness.c - host test driver for sdv_defences.c (NOT part of the embedded code).
 *
 *   harness cases.txt        replay recorded cases, print one RESULT line per case
 *   harness --sizeof         print the size of the state structure
 *   harness --bench N        time N synthetic frames on the host (a host figure, not an MCU figure)
 *
 * Case file format (text, generated by experiments/e16_embedded_feasibility.py):
 *   CASE <name> <policy> <auth>
 *   F <channel> <t_us> <dist_mm> <speed_mms> <obstacle> <mac_ok>      a received sensor (0) or radar (1) frame
 *   T <t_us>                                                          a watchdog check
 *   END
 * Output per case:  RESULT <name> <trigger code> <t_us of the trigger or -1> <rejected frames>
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "sdv_defences.h"

static int run_cases(const char *path)
{
    FILE *f = fopen(path, "r");
    char line[256];
    char name[128] = "";
    sdv_state_t st;
    sdv_config_t cfg;
    int in_case = 0, done = 0;
    long trigger_us = -1;
    int trigger = 0;

    if (!f) {
        fprintf(stderr, "cannot open %s\n", path);
        return 2;
    }
    while (fgets(line, sizeof line, f)) {
        if (strncmp(line, "CASE ", 5) == 0) {
            int policy = 0, auth = 0;
            if (sscanf(line + 5, "%127s %d %d", name, &policy, &auth) != 3) {
                fprintf(stderr, "bad CASE line: %s", line);
                fclose(f);
                return 2;
            }
            sdv_config_default(&cfg);
            cfg.policy = (uint8_t)policy;
            cfg.auth_enabled = (uint8_t)auth;
            sdv_init(&st, &cfg);
            in_case = 1;
            done = 0;
            trigger = 0;
            trigger_us = -1;
        } else if (strncmp(line, "END", 3) == 0 && in_case) {
            printf("RESULT %s %d %ld %lu\n", name, trigger, trigger_us, (unsigned long)st.rejected);
            in_case = 0;
        } else if (in_case && !done && line[0] == 'F') {
            unsigned ch, obs, mac;
            long t, d, v;
            if (sscanf(line + 2, "%u %ld %ld %ld %u %u", &ch, &t, &d, &v, &obs, &mac) == 6) {
                sdv_trigger_t r = sdv_on_frame(&st, (uint8_t)ch, (uint32_t)t, (int32_t)d, (int32_t)v,
                                               (uint8_t)obs, (uint8_t)mac);
                if (r != SDV_NO_TRIGGER) {
                    trigger = (int)r;
                    trigger_us = t;
                    done = 1;
                }
            }
        } else if (in_case && !done && line[0] == 'T') {
            long t;
            if (sscanf(line + 2, "%ld", &t) == 1) {
                sdv_trigger_t r = sdv_on_tick(&st, (uint32_t)t);
                if (r != SDV_NO_TRIGGER) {
                    trigger = (int)r;
                    trigger_us = t;
                    done = 1;
                }
            }
        }
    }
    fclose(f);
    return 0;
}

static int bench(long n)
{
    sdv_state_t st;
    sdv_config_t cfg;
    clock_t t0, t1;
    unsigned long sink = 0;
    long i;

    sdv_config_default(&cfg);
    cfg.policy = SDV_POLICY_DISAGREE;
    cfg.auth_enabled = 1u;
    sdv_init(&st, &cfg);
    t0 = clock();
    for (i = 0; i < n; i++) {
        /* far obstacle: never triggers, so every call runs the full path */
        sink += (unsigned long)sdv_on_frame(&st, (uint8_t)(i & 1), (uint32_t)(i * 10), 90000 + (int32_t)(i & 7),
                                            16667, 1u, 1u);
        sink += (unsigned long)sdv_on_tick(&st, (uint32_t)(i * 10));
    }
    t1 = clock();
    printf("BENCH frames=%ld ns_per_frame_plus_tick=%.1f sink=%lu\n", n,
           1e9 * ((double)(t1 - t0) / CLOCKS_PER_SEC) / (double)n, sink);
    return 0;
}

int main(int argc, char **argv)
{
    if (argc == 2 && strcmp(argv[1], "--sizeof") == 0) {
        printf("SIZEOF state=%lu config=%lu\n", (unsigned long)sizeof(sdv_state_t), (unsigned long)sizeof(sdv_config_t));
        return 0;
    }
    if (argc == 3 && strcmp(argv[1], "--bench") == 0) {
        return bench(atol(argv[2]));
    }
    if (argc == 2) {
        return run_cases(argv[1]);
    }
    fprintf(stderr, "usage: harness cases.txt | --sizeof | --bench N\n");
    return 2;
}
